-- AT-MOVEJOB part 1 (Airtable parity: a base moved between organizations ran every record validator TWICE per row).
--   Cause: custom.record is HASH partitioned on organization_id (16 partitions). custom.table_move re-files each row with
--   UPDATE ... SET organization_id = <to>; when <to> hashes to another partition Postgres runs that UPDATE as DELETE + INSERT:
--   the source partition's BEFORE UPDATE row triggers fire (their WHEN names old.organization_id IS DISTINCT FROM
--   new.organization_id, so every one fires), then the destination's BEFORE INSERT row triggers fire on the same row.
--   Twenty validators exist as an UPDATE copy + an INSERT twin ("…!i"): field_validation, _value_envelope, derived_fields,
--   organization_wall, rule_uses, choice_words, the shape/class/parity/merge/rule/table/work guards, promoted cap,
--   undeclared key, unique rule. _context_copy_fence is one INSERT OR UPDATE trigger, so it too ran on both halves.
--   Fix: each UPDATE copy stands down ONLY when custom._record_update_reroutes() says this UPDATE is a table_move
--   (custom.table_move_from set) whose new organization routes the row to ANOTHER partition — exactly when its INSERT
--   twin is guaranteed to judge the row. _context_copy_fence is split into an UPDATE copy (same guard) and an INSERT
--   twin, same position in the firing order. Ordinary writes: the WHEN tests the organization first, unchanged checks.
-- chair-step: replaces 21 BEFORE row triggers on custom.record (CREATE OR REPLACE TRIGGER, partitioned) and adds one INSERT twin; AT-MOVEJOB, authorized by the program's owning session.
-- Inverse: migrations/inverse/atmovejob_a_move_validators_once_down.sql

CREATE OR REPLACE FUNCTION custom._record_update_reroutes(p_old uuid, p_new uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
-- AT-MOVEJOB: true ONLY while custom.table_move is moving rows (custom.table_move_from is set) AND this UPDATE's new
-- organization lands the row in ANOTHER hash partition of custom.record. Only then does Postgres turn the UPDATE into
-- DELETE + INSERT, so every BEFORE INSERT twin ("…!i") judges the row again on the INSERT half and the BEFORE UPDATE
-- copy may stand down. Two organizations that hash to the SAME partition stay an ordinary UPDATE: false, both run.
-- Ordinary writes never reach this function (the trigger WHEN tests the organization first) and never stand down.
declare
  v_key  text;
  v_memo text;
  v_out  boolean := false;
begin
  if p_old is not distinct from p_new or coalesce(current_setting('custom.table_move_from', true), '') = '' then
    return false;
  end if;
  -- one move = one (from, to) pair; the answer is memoised for the transaction, never across it
  v_key  := p_old::text || '>' || p_new::text || '=';
  v_memo := coalesce(current_setting('custom._record_reroutes_memo', true), '');
  if starts_with(v_memo, v_key) then
    return right(v_memo, 1) = 't';
  end if;
  select not satisfies_hash_partition('custom.record'::regclass, b.m, b.r, p_new) into v_out
    from (select (regexp_match(pg_get_expr(c.relpartbound, c.oid), 'modulus (\d+), remainder (\d+)'))[1]::int as m,
                 (regexp_match(pg_get_expr(c.relpartbound, c.oid), 'modulus (\d+), remainder (\d+)'))[2]::int as r
            from pg_inherits i join pg_class c on c.oid = i.inhrelid
           where i.inhparent = 'custom.record'::regclass) b
   where b.m is not null and satisfies_hash_partition('custom.record'::regclass, b.m, b.r, p_old)
   limit 1;
  v_out := coalesce(v_out, false);
  perform set_config('custom._record_reroutes_memo', v_key || case when v_out then 't' else 'f' end, true);
  return v_out;
end
$function$;
-- Called from the WHEN of record triggers, so it runs as the WRITING role: a signed-in door, declared before the grant.
INSERT INTO platform.client_callable_door (schema_name, function_name, identity_args, identity_argtypes, declared_by, reason, signed_in_callers)
VALUES ('custom', '_record_update_reroutes', 'p_old uuid, p_new uuid', array['uuid'::regtype::oid, 'uuid'::regtype::oid], 'atmovejob_a_move_validators_once.sql',
        'Evaluated in the WHEN clause of 21 BEFORE UPDATE row triggers on custom.record, as whichever role writes the row (a signed-in person through the store doors). Reads only its two arguments, one GUC and the partition catalog; returns a boolean, touches nothing.', true);
GRANT EXECUTE ON FUNCTION custom._record_update_reroutes(uuid, uuid) TO authenticated, service_role;

CREATE OR REPLACE TRIGGER _value_envelope BEFORE UPDATE ON custom.record FOR EACH ROW WHEN ((((new.data_class IS DISTINCT FROM 'record'::text) OR (old.data_class IS DISTINCT FROM new.data_class) OR (old.data IS DISTINCT FROM new.data) OR (old.table_id IS DISTINCT FROM new.table_id) OR (old.organization_id IS DISTINCT FROM new.organization_id) OR (old.metadata IS DISTINCT FROM new.metadata) OR (old.custom_fields IS DISTINCT FROM new.custom_fields) OR (old.visibility IS DISTINCT FROM new.visibility))) AND ((old.organization_id IS NOT DISTINCT FROM new.organization_id) OR (NOT custom._record_update_reroutes(old.organization_id, new.organization_id)))) EXECUTE FUNCTION custom._value_envelope();
